//! Converts `PHPSRC/ext/mbstring/unicode_data.h` (generated by php-src's
//! `ext/mbstring/ucgendat/ucgendat.php` from the Unicode Character Database) into
//! `crates/twig-unicode/src/tables.rs`.
//!
//! The arrays are copied value for value and in the same order, so the property binary search
//! (`prop_lookup()`) and the minimal-perfect-hash case lookups (`mph_lookup()`) of
//! `PHPSRC/ext/mbstring/php_unicode.c` work on the Rust tables unchanged.
//!
//! Usage (see README.md):
//!
//! ```text
//! cargo +stable run --manifest-path crates/twig-unicode/gen/Cargo.toml -- \
//!     <php-src-8.5.13>/ext/mbstring/unicode_data.h crates/twig-unicode/src/tables.rs
//! ```

use std::collections::BTreeMap;
use std::fmt::Write as _;
use std::process::ExitCode;

/// Number of properties php-src 8.5.13 generates (`UC_MN` .. `UC_CASE_IGNORABLE`, `php_unicode.h`).
const EXPECTED_PROPS: usize = 37;

/// One `static const` declaration of the C header.
#[derive(Debug)]
enum Decl {
    Scalar { ctype: String, value: i64 },
    Array { ctype: String, values: Vec<i64> },
}

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().collect();
    if args.len() != 3 {
        eprintln!("usage: twig-unicode-gen <php-src>/ext/mbstring/unicode_data.h <out>/tables.rs");
        return ExitCode::from(2);
    }
    let source = match std::fs::read_to_string(&args[1]) {
        Ok(source) => source,
        Err(err) => {
            eprintln!("cannot read {}: {err}", args[1]);
            return ExitCode::FAILURE;
        }
    };
    let rust = match parse_header(&source).and_then(|decls| generate(&decls)) {
        Ok(rust) => rust,
        Err(err) => {
            eprintln!("{}: {err}", args[1]);
            return ExitCode::FAILURE;
        }
    };
    if let Err(err) = std::fs::write(&args[2], rust) {
        eprintln!("cannot write {}: {err}", args[2]);
        return ExitCode::FAILURE;
    }
    eprintln!("wrote {}", args[2]);
    ExitCode::SUCCESS
}

/// Removes `/* ... */` comments (the header has no `//` comments and no string literals).
fn strip_comments(source: &str) -> Result<String, String> {
    let mut out = String::with_capacity(source.len());
    let mut rest = source;
    while let Some(start) = rest.find("/*") {
        out.push_str(&rest[..start]);
        let end = rest[start + 2..]
            .find("*/")
            .ok_or_else(|| "unterminated comment".to_string())?;
        rest = &rest[start + 2 + end + 2..];
    }
    out.push_str(rest);
    Ok(out)
}

fn parse_int(token: &str) -> Result<i64, String> {
    let token = token.trim();
    let (negative, digits) = match token.strip_prefix('-') {
        Some(rest) => (true, rest.trim()),
        None => (false, token),
    };
    let value = if let Some(hex) = digits
        .strip_prefix("0x")
        .or_else(|| digits.strip_prefix("0X"))
    {
        i64::from_str_radix(hex, 16)
    } else {
        digits.parse::<i64>()
    }
    .map_err(|err| format!("bad integer literal {token:?}: {err}"))?;
    Ok(if negative { -value } else { value })
}

/// Parses every `static const <type> <name> = <value>;` and `static const <type> <name>[] = {...};`.
fn parse_header(source: &str) -> Result<BTreeMap<String, Decl>, String> {
    let code = strip_comments(source)?;
    let mut decls = BTreeMap::new();
    for statement in code.split(';') {
        let statement = statement.trim();
        if statement.is_empty() {
            continue;
        }
        let Some(rest) = statement.strip_prefix("static const ") else {
            return Err(format!("unexpected statement: {statement:.60}"));
        };
        let (name, decl) = if let Some((head, body)) = rest.split_once('{') {
            let body = body
                .trim()
                .strip_suffix('}')
                .ok_or_else(|| format!("array without closing brace: {head}"))?;
            let head = head.trim().strip_suffix('=').map(str::trim).unwrap_or(head);
            let head = head
                .strip_suffix("[]")
                .ok_or_else(|| format!("array declaration without []: {head}"))?;
            let (ctype, name) = split_type_and_name(head)?;
            let values = body
                .split(',')
                .filter(|v| !v.trim().is_empty())
                .map(parse_int)
                .collect::<Result<Vec<_>, _>>()?;
            (name, Decl::Array { ctype, values })
        } else {
            let (head, value) = rest
                .split_once('=')
                .ok_or_else(|| format!("scalar without value: {rest}"))?;
            let (ctype, name) = split_type_and_name(head)?;
            (
                name,
                Decl::Scalar {
                    ctype,
                    value: parse_int(value)?,
                },
            )
        };
        if decls.insert(name.clone(), decl).is_some() {
            return Err(format!("duplicate declaration of {name}"));
        }
    }
    Ok(decls)
}

fn split_type_and_name(head: &str) -> Result<(String, String), String> {
    let words: Vec<&str> = head.split_whitespace().collect();
    match words.split_last() {
        Some((name, ctype)) if !ctype.is_empty() => Ok((ctype.join(" "), (*name).to_string())),
        _ => Err(format!("cannot split type and name: {head:?}")),
    }
}

struct Tables<'a> {
    decls: &'a BTreeMap<String, Decl>,
}

impl Tables<'_> {
    fn scalar(&self, name: &str, ctype: &str) -> Result<i64, String> {
        match self.decls.get(name) {
            Some(Decl::Scalar { ctype: t, value }) if t == ctype => Ok(*value),
            Some(other) => Err(format!(
                "{name}: expected scalar of type {ctype}, got {other:?}"
            )),
            None => Err(format!("{name}: missing")),
        }
    }

    fn array(&self, name: &str, ctype: &str, min: i64, max: i64) -> Result<&[i64], String> {
        match self.decls.get(name) {
            Some(Decl::Array { ctype: t, values }) if t == ctype => {
                if let Some(bad) = values.iter().find(|v| !(min..=max).contains(*v)) {
                    return Err(format!("{name}: value {bad} does not fit {ctype}"));
                }
                Ok(values)
            }
            Some(Decl::Array { ctype: t, .. }) => {
                Err(format!("{name}: expected element type {ctype}, got {t}"))
            }
            Some(_) => Err(format!("{name}: expected an array")),
            None => Err(format!("{name}: missing")),
        }
    }
}

const U16_MAX: i64 = u16::MAX as i64;
const U32_MAX: i64 = u32::MAX as i64;
const I16_MIN: i64 = i16::MIN as i64;
const I16_MAX: i64 = i16::MAX as i64;

fn generate(decls: &BTreeMap<String, Decl>) -> Result<String, String> {
    let t = Tables { decls };
    let expected: Vec<&str> = [
        "_ucprop_size",
        "_ucprop_offsets",
        "_ucprop_ranges",
        "_uccase_extra_table",
    ]
    .into_iter()
    .chain(CASES.iter().flat_map(|c| c.c_names()))
    .collect();
    if let Some(unknown) = decls.keys().find(|k| !expected.contains(&k.as_str())) {
        return Err(format!(
            "unexpected declaration {unknown} (did ucgendat.php change?)"
        ));
    }

    let prop_size = t.scalar("_ucprop_size", "unsigned short")?;
    if prop_size != EXPECTED_PROPS as i64 {
        return Err(format!(
            "_ucprop_size is {prop_size}, expected {EXPECTED_PROPS}"
        ));
    }
    let offsets = t.array("_ucprop_offsets", "unsigned short", 0, U16_MAX)?;
    let ranges = t.array("_ucprop_ranges", "unsigned int", 0, U32_MAX)?;
    if offsets.len() < EXPECTED_PROPS + 1 || offsets.len() % 4 != 0 {
        return Err(format!("_ucprop_offsets has {} entries", offsets.len()));
    }
    if offsets[EXPECTED_PROPS] as usize != ranges.len() {
        return Err("_ucprop_offsets sentinel does not match _ucprop_ranges".to_string());
    }
    if offsets[..=EXPECTED_PROPS]
        .windows(2)
        .any(|w| w[0] > w[1] || w[0] % 2 != 0)
    {
        return Err("_ucprop_offsets is not ascending and even".to_string());
    }
    for (prop, w) in offsets[..=EXPECTED_PROPS].windows(2).enumerate() {
        let pairs = &ranges[w[0] as usize..w[1] as usize];
        for pair in pairs.chunks(2) {
            if pair[0] > pair[1] {
                return Err(format!("property {prop}: inverted range {pair:x?}"));
            }
        }
        if pairs
            .chunks(2)
            .collect::<Vec<_>>()
            .windows(2)
            .any(|p| p[0][1] >= p[1][0])
        {
            return Err(format!(
                "property {prop}: ranges are not sorted and disjoint"
            ));
        }
    }

    let extra = t.array("_uccase_extra_table", "unsigned", 0, U32_MAX)?;

    let mut out = String::new();
    out.push_str(HEADER);
    writeln!(out).unwrap();
    writeln!(out, "/// Number of properties (`_ucprop_size`).").unwrap();
    writeln!(out, "pub(crate) const UCPROP_SIZE: usize = {prop_size};").unwrap();
    writeln!(out).unwrap();
    writeln!(
        out,
        "/// Start of each property's range pairs in [`UCPROP_RANGES`], then a sentinel and zero\n\
         /// padding (`_ucprop_offsets`)."
    )
    .unwrap();
    write_array(&mut out, "UCPROP_OFFSETS", "u16", offsets, 8, |v| {
        format!("0x{v:04x}")
    });
    writeln!(
        out,
        "/// Inclusive `[first, last]` code point ranges of every property, sorted per property\n\
         /// (`_ucprop_ranges`)."
    )
    .unwrap();
    write_array(&mut out, "UCPROP_RANGES", "u32", ranges, 4, |v| {
        format!("0x{v:08x}")
    });

    for case in CASES {
        let [g_size_name, g_name, table_size_name, table_name] = case.c_names();
        let g_size = t.scalar(g_size_name, "unsigned")?;
        let g = t.array(g_name, "short", I16_MIN, I16_MAX)?;
        let table_size = t.scalar(table_size_name, "unsigned")?;
        let table = t.array(table_name, "unsigned", 0, U32_MAX)?;
        if g.len() as i64 != g_size || g.is_empty() {
            return Err(format!(
                "{g_name} has {} entries, {g_size_name} = {g_size}",
                g.len()
            ));
        }
        if table.len() as i64 != 2 * table_size || table.is_empty() {
            return Err(format!(
                "{table_name} has {} entries, {table_size_name} = {table_size}",
                table.len()
            ));
        }
        for pair in table.chunks(2) {
            let value = pair[1];
            if value > 0xFF_FFFF {
                // A special-casing sequence: length in the top byte, index into the extra table
                // whose first entry is the simple mapping (`prepareCaseData()` in ucgendat.php).
                let len = (value >> 24) as usize;
                let idx = (value & 0xFF_FFFF) as usize;
                if !(1..=3).contains(&len) || idx + len >= extra.len() {
                    return Err(format!("{table_name}: bad special casing entry {value:#x}"));
                }
            }
        }
        let upper = case.name.to_uppercase();
        writeln!(
            out,
            "/// Displacements of the minimal perfect hash for {} mappings (`{g_name}`).",
            case.doc
        )
        .unwrap();
        write_array(&mut out, &format!("UCCASE_{upper}_G"), "i16", g, 8, |v| {
            format!("{v:6}")
        });
        writeln!(
            out,
            "/// `[code, mapping]` pairs of the {} mappings in hash order (`{table_name}`). A mapping\n\
             /// above `0xFFFFFF` holds a sequence length in its top byte and an index into\n\
             /// [`UCCASE_EXTRA_TABLE`].",
            case.doc
        )
        .unwrap();
        write_array(
            &mut out,
            &format!("UCCASE_{upper}_TABLE"),
            "u32",
            table,
            4,
            |v| format!("0x{v:08x}"),
        );
    }

    writeln!(
        out,
        "/// Special-casing sequences: the simple mapping followed by the full mapping\n\
         /// (`_uccase_extra_table`)."
    )
    .unwrap();
    write_array(&mut out, "UCCASE_EXTRA_TABLE", "u32", extra, 4, |v| {
        format!("0x{v:08x}")
    });
    Ok(out)
}

struct Case {
    name: &'static str,
    doc: &'static str,
    /// `_uccase_<name>_g_size`, `_uccase_<name>_g`, `_uccase_<name>_table_size`, `_uccase_<name>_table`.
    c_names: [&'static str; 4],
}

impl Case {
    fn c_names(&self) -> [&'static str; 4] {
        self.c_names
    }
}

macro_rules! case {
    ($name:literal, $doc:literal) => {
        Case {
            name: $name,
            doc: $doc,
            c_names: [
                concat!("_uccase_", $name, "_g_size"),
                concat!("_uccase_", $name, "_g"),
                concat!("_uccase_", $name, "_table_size"),
                concat!("_uccase_", $name, "_table"),
            ],
        }
    };
}

const CASES: &[Case] = &[
    case!("upper", "upper-case"),
    case!("lower", "lower-case"),
    case!("title", "title-case"),
    case!("fold", "case-folding"),
];

fn write_array(
    out: &mut String,
    name: &str,
    rust_type: &str,
    values: &[i64],
    per_line: usize,
    fmt: impl Fn(i64) -> String,
) {
    writeln!(
        out,
        "pub(crate) static {name}: [{rust_type}; {}] = [",
        values.len()
    )
    .unwrap();
    for line in values.chunks(per_line) {
        let items: Vec<String> = line.iter().map(|&v| fmt(v)).collect();
        writeln!(out, "    {},", items.join(", ")).unwrap();
    }
    writeln!(out, "];").unwrap();
    writeln!(out).unwrap();
}

const HEADER: &str = "\
// @generated by crates/twig-unicode/gen (see its README.md). DO NOT EDIT.
//
// Source: PHPSRC/ext/mbstring/unicode_data.h of php-src 8.5.13, which php-src generates with
// PHPSRC/ext/mbstring/ucgendat/ucgendat.php from the Unicode 17.0 Character Database
// (UnicodeData.txt, CaseFolding.txt, SpecialCasing.txt, DerivedCoreProperties.txt).
//
// Licences: the data is derived from the Unicode Character Database, Copyright (c) Unicode, Inc.,
// distributed under the Unicode License v3 (Unicode-3.0). The table layout and the lookup
// scheme are php-src's (PHP License 3.01; ucgendat.php itself is based on OpenLDAP's ucgendat.c
// and on ucdata-2.5, Copyright 2001 Computing Research Labs, New Mexico State University).

//! Unicode 17.0 property and case-mapping tables of PHP's mbstring, converted value for value
//! from `PHPSRC/ext/mbstring/unicode_data.h`.
";
